pub fn apply_inverse(inverse: &GltfCreateNodeInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfCreateNodeInverseOperation::Insert { position, .. } if *position > after.document.nodes.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/nodes", "position must be within the collection")), GltfCreateNodeInverseOperation::Delete { index, .. } if *index >= after.document.nodes.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/nodes", "index must address an item")), GltfCreateNodeInverseOperation::Move { index, position } if *index >= after.document.nodes.len() || *position >= after.document.nodes.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/nodes", "indices must address items")), GltfCreateNodeInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.nodes.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.nodes.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/nodes", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfCreateNodeInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Nodes, &Change::Insert(*position))?; next.document.nodes.insert(*position, item.clone());  }, GltfCreateNodeInverseOperation::Delete { index, .. } => { nodes_op(&mut next, GltfTopLevelFamily::Nodes, *index, None, None)?;  }, GltfCreateNodeInverseOperation::Move { index, position } => { nodes_op(&mut next, GltfTopLevelFamily::Nodes, *index, Some(*position), None)?;  }, GltfCreateNodeInverseOperation::Reorder { order } => { nodes_op(&mut next, GltfTopLevelFamily::Nodes, order[0], None, Some(order))?;  } } Ok(next) }
